// FindResource retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindResource(ctx context.Context, exec bob.Executor, IDPK string, cols ...string) (*Resource, error) {
	if len(cols) == 0 {
		return Resources.Query(
			sm.Where(Resources.Columns.ID.EQ(psql.Arg(IDPK))),
		).One(ctx, exec)
	}

	return Resources.Query(
		sm.Where(Resources.Columns.ID.EQ(psql.Arg(IDPK))),
		sm.Columns(Resources.Columns.Only(cols...)),
	).One(ctx, exec)
}

// ResourceExists checks the presence of a single record by primary key
func ResourceExists(ctx context.Context, exec bob.Executor, IDPK string) (bool, error) {
	return Resources.Query(
		sm.Where(Resources.Columns.ID.EQ(psql.Arg(IDPK))),
	).Exists(ctx, exec)
}

// AfterQueryHook is called after Resource is retrieved from the database
func (o *Resource) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Resources.AfterSelectHooks.RunHooks(ctx, exec, ResourceSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = Resources.AfterInsertHooks.RunHooks(ctx, exec, ResourceSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = Resources.AfterUpdateHooks.RunHooks(ctx, exec, ResourceSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = Resources.AfterDeleteHooks.RunHooks(ctx, exec, ResourceSlice{o})
	case bob.QueryTypeMerge:
		ctx, err = Resources.AfterMergeHooks.RunHooks(ctx, exec, ResourceSlice{o})
	}

	return err
}

// primaryKeyVals returns the primary key values of the Resource
func (o *Resource) primaryKeyVals() bob.Expression {
	return psql.Arg(o.ID)
}

func (o *Resource) pkEQ() dialect.Expression {
	return psql.Quote("resources", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		return o.primaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

// Update uses an executor to update the Resource
func (o *Resource) Update(ctx context.Context, exec bob.Executor, s *ResourceSetter) error {
	v, err := Resources.Update(s.UpdateMod(), um.Where(o.pkEQ())).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R = v.R
	*o = *v

	return nil
}

// Delete deletes a single Resource record with an executor
func (o *Resource) Delete(ctx context.Context, exec bob.Executor) error {
	_, err := Resources.Delete(dm.Where(o.pkEQ())).Exec(ctx, exec)
	return err
}

// Reload refreshes the Resource using the executor
func (o *Resource) Reload(ctx context.Context, exec bob.Executor) error {
	o2, err := Resources.Query(
		sm.Where(Resources.Columns.ID.EQ(psql.Arg(o.ID))),
	).One(ctx, exec)
	if err != nil {
		return err
	}
	o2.R = o.R
	*o = *o2

	return nil
}

// AfterQueryHook is called after ResourceSlice is retrieved from the database
func (o ResourceSlice) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Resources.AfterSelectHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeInsert:
		ctx, err = Resources.AfterInsertHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeUpdate:
		ctx, err = Resources.AfterUpdateHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeDelete:
		ctx, err = Resources.AfterDeleteHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeMerge:
		ctx, err = Resources.AfterMergeHooks.RunHooks(ctx, exec, o)
	}

	return err
}

func (o ResourceSlice) pkIN() dialect.Expression {
	if len(o) == 0 {
		return psql.Raw("NULL")
	}

	return psql.Quote("resources", "id").In(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		pkPairs := make([]bob.Expression, len(o))
		for i, row := range o {
			pkPairs[i] = row.primaryKeyVals()
		}
		return bob.ExpressSlice(ctx, w, d, start, pkPairs, "", ", ", "")
	}))
}

// copyMatchingRows finds models in the given slice that have the same primary key
// then it first copies the existing relationships from the old model to the new model
// and then replaces the old model in the slice with the new model
func (o ResourceSlice) copyMatchingRows(from ...*Resource) {
	fromByPK := make(map[string]*Resource, len(from))
	for _, new := range from {
		// keep the first row for each key, like the nested loop did
		if _, ok := fromByPK[new.ID]; !ok {
			fromByPK[new.ID] = new
		}
	}

	for i, old := range o {
		new, ok := fromByPK[old.ID]
		if !ok {
			continue
		}
		new.R = old.R
		o[i] = new
	}
}

// UpdateMod modifies an update query with "WHERE primary_key IN (o...)"
func (o ResourceSlice) UpdateMod() bob.Mod[*dialect.UpdateQuery] {
	return bob.ModFunc[*dialect.UpdateQuery](func(q *dialect.UpdateQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Resources.BeforeUpdateHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Resource:
				o.copyMatchingRows(retrieved)
			case []*Resource:
				o.copyMatchingRows(retrieved...)
			case ResourceSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Resource or a slice of Resource
				// then run the AfterUpdateHooks on the slice
				_, err = Resources.AfterUpdateHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// DeleteMod modifies an delete query with "WHERE primary_key IN (o...)"
func (o ResourceSlice) DeleteMod() bob.Mod[*dialect.DeleteQuery] {
	return bob.ModFunc[*dialect.DeleteQuery](func(q *dialect.DeleteQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Resources.BeforeDeleteHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Resource:
				o.copyMatchingRows(retrieved)
			case []*Resource:
				o.copyMatchingRows(retrieved...)
			case ResourceSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Resource or a slice of Resource
				// then run the AfterDeleteHooks on the slice
				_, err = Resources.AfterDeleteHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// MergeMod modifies a merge query to run BeforeMergeHooks and AfterMergeHooks
// and updates the slice with the returned rows.
func (o ResourceSlice) MergeMod() bob.Mod[*dialect.MergeQuery] {
	return bob.ModFunc[*dialect.MergeQuery](func(q *dialect.MergeQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Resources.BeforeMergeHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Resource:
				o.copyMatchingRows(retrieved)
			case []*Resource:
				o.copyMatchingRows(retrieved...)
			case ResourceSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Resource or a slice of Resource
				// then run the AfterMergeHooks on the slice
				_, err = Resources.AfterMergeHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))
	})
}

func (o ResourceSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals ResourceSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Resources.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o ResourceSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Resources.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o ResourceSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := Resources.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

