// HasTerms filters parents that have a matching Terms (a
// many-to-many relationship) using a correlated EXISTS subquery instead of
// INNER JOINs, so the parent rows are not multiplied. The optional filters are
// applied to the subquery (i.e. to Terms).
func (w resourceWhereR[Q]) HasTerms(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(ResourceKeywords.NameExpr()),
		sm.InnerJoin(Terms.NameExpr()).On(
			Terms.Columns.ID.EQ(ResourceKeywords.Columns.Keyword),
		),
		sm.Where(ResourceKeywords.Columns.ResourceID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}
